{"file_path": "/app/work/load.py", "content": """"Parse the live session transcript into structured physim run records.

The transcript jsonl is appended as the session proceeds, so re-importing this
module (or calling load()) always picks up every run made so far -- no manual
transcription needed.
"""
import json, os, glob

TRANS_GLOB = ".vf-claude/*/projects/-app/*.jsonl"


def _transcripts():
    return sorted(glob.glob(os.path.join("/app", TRANS_GLOB)))


def load():
    uses, res = {}, {}
    order = []
    for p in _transcripts():
        for line in open(p):
            try:
                o = json.loads(line)
            except Exception:
                continue
            m = o.get("message") or {}
            c = m.get("content")
            if not isinstance(c, list):
                continue
            for b in c:
                if not isinstance(b, dict):
                    continue
                if b.get("type") == "tool_use" and "physim" in str(b.get("name", "")):
                    if b["id"] not in uses:
                        order.append(b["id"])
                    uses[b["id"]] = (b["name"], b["input"])
                if b.get("type") == "tool_result":
                    cc = b.get("content")
                    if isinstance(cc, list):
                        txt = "".join(x.get("text", "") for x in cc if isinstance(x, dict))
                    else:
                        txt = str(cc)
                    res[b["tool_use_id"]] = txt
    recs = []
    for k in order:
        if k not in res:
            continue
        name, inp = uses[k]
        raw = res[k]
        try:
            payload = json.loads(raw)
            if isinstance(payload, dict) and "result" in payload:
                payload = json.loads(payload["result"])
        except Exception:
            payload = {"raw": raw}
        recs.append({"tool": name, "input": inp, "out": payload})
    return recs


def runs():
    out = []
    for r in load():
        if not r["tool"].endswith("run"):
            continue
        o = r["out"]
        if not isinstance(o, dict) or "tail_mean" not in o:
            continue
        out.append({
            "segments": r["input"]["segments"],
            "channels": r["input"].get("channels"),
            "tail_mean": {int(k): v for k, v in o["tail_mean"].items()},
            "tail_sd": {int(k): v for k, v in o.get("tail_sd", {}).items()},
            "series": {int(k): v for k, v in o.get("series", {}).items()},
            "stride": o.get("series_stride"),
            "ticks": o.get("ticks_run"),
            "budget_left": o.get("budget_left"),
        })
    return out


CONST_CH = [1, 6, 22, 23, 26, 31, 45, 48, 51, 55]
VAR_CH = [c for c in range(60) if c not in CONST_CH]

if __name__ == "__main__":
    R = runs()
    print(len(R), "runs; budget_left", R[-1]["budget_left"])
"}

