import numpy as np
TAU=300.0; A0=1.0; TH0=0.3087; KAP=2.3; ACAP=0.62; TAUX=8.0
GH=np.load('ghat.npy')
def expand(segments):
    out=[]
    for sg in segments:
        n=int(sg['t'])
        if 'u' in sg: u=np.array(sg['u'],float); out.append((n,u,u))
        else: out.append((n,np.array(sg['u_start'],float),np.array(sg['u_end'],float)))
    return out
def trace(segments,a0=0.0,s0=None,x0=0.0,settle=12):
    """returns arrays x(t),a(t),u(t) per tick"""
    segs=expand(segments); N=sum(s[0] for s in segs)
    X=np.zeros(N); A=np.zeros(N); Uu=np.zeros((N,10))
    a=a0; s=s0; x=x0; i=0
    for (n,ua,ub) in segs:
        for k in range(n):
            u=np.clip(ua+(ub-ua)*((k+0.5)/max(n,1)),-1,1)
            b=float(GH@u)
            if s is None:
                if abs(b)>0.02: s=int(np.sign(b))
                elif i>=settle: s=1
            if s is not None:
                a+=(s*A0-a)/TAU; a=float(np.clip(a,-ACAP,ACAP))
                if s*a>TH0+KAP*s*b: s=-s
                x+=(s-x)/TAUX
            X[i]=x; A[i]=a; Uu[i]=u; i+=1
    return X,A,Uu
def feat(segments,a0=0.0,s0=None):
    X,A,U=trace(segments,a0,s0)
    w=slice(max(0,len(X)-20),len(X))
    return np.concatenate([[1.0,X[w].mean(),A[w].mean()],U[w].mean(0)])
